journal_setup.text:
func NewJournal(config JournalConfig) *Journal {
	if config.QueueSize <= 0 {
		config.QueueSize = DefaultQueueSize
	}
	if config.Capacity <= 0 {
		config.Capacity = DefaultCapacity
	}
	if config.PublishTimeout <= 0 {
		config.PublishTimeout = DefaultPublishTimeout
	}
	if config.Now == nil {
		config.Now = time.Now
	}
	journal := &Journal{config: config, queue: make(chan Decision, config.QueueSize),
		ring: make([]Decision, config.Capacity), ids: map[string]bool{},
		subscribers: map[*subscriber]struct{}{}}
	journal.Attach(config.Sink, config.Archive)
	return journal
}

// Attach sets the durable sink and archive. Decisions recorded before a sink
// is attached stay queued (up to the queue bound) and are published once it
// is.
func (journal *Journal) Attach(sink Sink, archive Archive) {
	if sink == nil && archive == nil {
		return
	}
	journal.storage.Store(&storageHolder{sink: sink, archive: archive})
}

func (journal *Journal) currentStorage() (Sink, Archive) {
	if holder := journal.storage.Load(); holder != nil {
		return holder.sink, holder.archive
	}
	return nil, nil
}

// Record indexes the decision, queues it for publishing and returns its ID.
// A full queue drops the durable copy and counts it; the in-memory copy and

type fakeSink struct {
	mu        sync.Mutex
	stored    []Decision
	failures  int
	block     chan struct{}
	attempted atomic.Int64
}

func (sink *fakeSink) Publish(ctx context.Context, decision Decision) error {
	sink.attempted.Add(1)
	if sink.block != nil {
		select {
		case <-sink.block:
		case <-ctx.Done():
			return ctx.Err()
		}
	}
	sink.mu.Lock()
	defer sink.mu.Unlock()
	if sink.failures > 0 {
		sink.failures--
		return errors.New("unavailable")
	}
	sink.stored = append(sink.stored, decision)
	return nil
}

func (sink *fakeSink) count() int {
	sink.mu.Lock()
	defer sink.mu.Unlock()
	return len(sink.stored)
}

type fakeArchive struct {
	decisions []Decision
	complete  bool
	scans     atomic.Int64
}

func (archive *fakeArchive) Scan(_ context.Context, since time.Time, maxScan int, visit func(Decision) bool) (bool, error) {
	archive.scans.Add(1)
	scanned := 0
	for _, decision := range archive.decisions {
		if decision.Time.Before(since) {
			continue
		}
		if scanned == maxScan {
			return false, nil
		}
		scanned++
		if !visit(decision) {
			return true, nil
		}
	}
	return archive.complete, nil
}

func waitFor(t *testing.T, condition func() bool) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for !condition() {
		if time.Now().After(deadline) {
			t.Fatal("condition not reached")
		}
		time.Sleep(5 * time.Millisecond)
	}
}

journal_ingest.text:
func (journal *Journal) Ingest(decision Decision) bool {
	fresh, _ := journal.ingest(decision, true)
	return fresh
}

// ingest indexes decision. durable marks it as stored in the stream. It
// reports whether the decision was new and whether it is known durable.
func (journal *Journal) ingest(decision Decision, durable bool) (bool, bool) {
	journal.mu.Lock()
	defer journal.mu.Unlock()
	if known, seen := journal.ids[decision.ID]; seen {
		if durable && !known {
			journal.ids[decision.ID] = true
		}
		return false, known || durable
	}
	ingestedTotal.Inc()
	capacity := len(journal.ring)
	if journal.size == capacity {
		evicted := journal.ring[journal.start]
		delete(journal.ids, evicted.ID)
		if evicted.Time.After(journal.coveredFrom) {
			journal.coveredFrom = evicted.Time
		}
		journal.ring[journal.start] = decision
		journal.start = (journal.start + 1) % capacity
	} else {
		journal.ring[(journal.start+journal.size)%capacity] = decision
		journal.size++
	}
	journal.ids[decision.ID] = durable
	for subscriber := range journal.subscribers {
		select {
		case subscriber.decisions <- decision:
		default:
		}
	}
	return true, durable
}

// MarkCoveredFrom records that decisions older than at may exist in the
// archive but not in memory, for example after a bounded warm start.
func (journal *Journal) MarkCoveredFrom(at time.Time) {
	journal.mu.Lock()
	defer journal.mu.Unlock()
	if at.After(journal.coveredFrom) {
		journal.coveredFrom = at
	}
}

// snapshot returns the indexed decisions, unordered, and the time from which
// the index is complete.
func (journal *Journal) snapshot() ([]Decision, time.Time) {
	journal.mu.RLock()
	defer journal.mu.RUnlock()
	decisions := make([]Decision, 0, journal.size)
	for offset := range journal.size {
		decisions = append(decisions, journal.ring[(journal.start+offset)%len(journal.ring)])
	}
	return decisions, journal.coveredFrom
}

// Query returns matching decisions newest first. A range older than the
// in-memory window is read from the archive when one is attached, and

journal_writer.text:
func (journal *Journal) Record(ctx context.Context, decision Decision) string {
	if decision.Region == "" {
		decision.Region = journal.config.Region
	}
	if decision.Actor.Member == "" {
		decision.Actor.Member = journal.config.Member
	}
	decision = decision.Normalize(journal.config.Now())
	// A decision with a caller-chosen ID that is already indexed (an
	// idempotent replay) is indexed and logged once. Its durable copy is
	// queued again unless it is known to be stored, since the first attempt
	// may have been dropped from a full queue or failed to publish; the
	// stream deduplicates a copy that did land by its message ID.
	if fresh, durable := journal.ingest(decision, false); !fresh {
		if !durable {
			journal.enqueue(decision)
		}
		return decision.ID
	}
	journal.recorded.Add(1)
	recordedTotal.Inc()
	if journal.config.Log {
		LogRecorder{}.Record(ctx, decision)
	}
	journal.enqueue(decision)
	return decision.ID
}

func (journal *Journal) enqueue(decision Decision) {
	select {
	case journal.queue <- decision:
		queueDepth.Add(1)
	default:
		journal.dropped.Add(1)
		droppedQueueFull.Inc()
	}
}

// markDurable records that an indexed decision is stored in the stream.
func (journal *Journal) markDurable(id string) {
	journal.mu.Lock()
	defer journal.mu.Unlock()
	if _, indexed := journal.ids[id]; indexed {
		journal.ids[id] = true
	}
}

// Run publishes queued decisions until ctx ends. A publish is retried a few
// times with the same message ID, so the stream deduplicates a retry whose
// first attempt was stored; a decision that still fails is dropped and
// counted.
func (journal *Journal) Run(ctx context.Context) error {
	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		case decision := <-journal.queue:
			queueDepth.Add(-1)
			journal.publish(ctx, decision)
		}
	}
}

func (journal *Journal) publish(ctx context.Context, decision Decision) {
	backoff := 250 * time.Millisecond
	for attempt := 1; ; attempt++ {
		sink, _ := journal.currentStorage()
		if sink == nil {
			// No stream yet: wait for one without holding up shutdown.
			select {
			case <-ctx.Done():
				return
			case <-time.After(backoff):
			}
			backoff = min(backoff*2, 5*time.Second)
			attempt = 0
			continue
		}
		publishCtx, cancel := context.WithTimeout(ctx, journal.config.PublishTimeout)
		err := sink.Publish(publishCtx, decision)
		cancel()
		if err == nil {
			journal.published.Add(1)
			publishedTotal.Inc()
			journal.markDurable(decision.ID)
			return
		}
		if ctx.Err() != nil || attempt >= publishAttempts {
			journal.failed.Add(1)
			droppedPublish.Inc()
			return
		}
		publishRetries.Inc()
		select {
		case <-ctx.Done():
			journal.failed.Add(1)
			droppedPublish.Inc()
			return
		case <-time.After(backoff):
		}
		backoff *= 2
	}
}

// Ingest adds a decision read from the durable stream to the in-memory index
// and notifies subscribers. A decision already indexed is ignored, so the
// stream tail can replay what this member recorded itself. It reports whether

func (journal *Journal) Stats() Stats {
	journal.mu.RLock()
	indexed := journal.size
	journal.mu.RUnlock()
	return Stats{Recorded: journal.recorded.Load(), Published: journal.published.Load(),
		DroppedQueue: journal.dropped.Load(), PublishFailed: journal.failed.Load(), Indexed: indexed,
		Queued: len(journal.queue)}
}

func NewID() string { return newIDAt(time.Now()) }

func newIDAt(at time.Time) string { return entityid.NewAt(at) }

// Normalize fills defaults and enforces bounds. It never fails: a record that
// is too large loses detail rather than being dropped.
func (decision Decision) Normalize(now time.Time) Decision {
	decision.Version = Version
	if decision.Time.IsZero() {
		decision.Time = now
	}
	decision.Time = decision.Time.UTC()
	if !entityid.Valid(decision.ID) {
		decision.ID = newIDAt(decision.Time)
	}
	if decision.Status == "" {
		decision.Status = StatusSucceeded
	}
	decision.Region = strings.ToLower(clip(decision.Region, 64))
	decision.Kind = Kind(clip(string(decision.Kind), 64))
	decision.Actor.Slice = clip(decision.Actor.Slice, 64)
	decision.Actor.Member = clip(decision.Actor.Member, maxIdentityBytes)
	decision.Subject.Kind = clip(decision.Subject.Kind, 64)
	decision.Subject.ID = clip(decision.Subject.ID, maxIdentityBytes)
	decision.Subject.Name = clip(decision.Subject.Name, maxIdentityBytes)
	decision.Summary = clip(decision.Summary, maxSummaryBytes)
	decision.Reason = clip(decision.Reason, maxSummaryBytes)
	decision.Rule = clip(decision.Rule, maxTextBytes)
	decision.Outcome = clip(decision.Outcome, maxTextBytes)
	decision.ParentID = clip(decision.ParentID, 64)
	if len(decision.Signals) > maxSignals {
		decision.Signals = decision.Signals[:maxSignals]
	}
	decision.Signals = slices.Clone(decision.Signals)
	for index := range decision.Signals {
		signal := &decision.Signals[index]
		signal.Name = clip(signal.Name, 128)
		signal.Text = clip(signal.Text, maxTextBytes)
		signal.Unit = clip(signal.Unit, 32)
		signal.Comparison = clip(signal.Comparison, 8)
	}
	if len(decision.Alternatives) > maxAlternatives {
		decision.Alternatives = decision.Alternatives[:maxAlternatives]
	}
	decision.Alternatives = slices.Clone(decision.Alternatives)
	for index := range decision.Alternatives {
		decision.Alternatives[index].Option = clip(decision.Alternatives[index].Option, maxTextBytes)
		decision.Alternatives[index].Reason = clip(decision.Alternatives[index].Reason, maxTextBytes)
	}
	if len(decision.Related) > maxRelated {
		decision.Related = decision.Related[:maxRelated]
	}
	decision.Related = slices.Clone(decision.Related)
	for index := range decision.Related {
		decision.Related[index] = clip(decision.Related[index], 64)
	}
	if len(decision.Attrs) > 0 {
		attrs := make(map[string]string, min(len(decision.Attrs), maxAttrs))
		for _, key := range slices.Sorted(maps.Keys(decision.Attrs)) {
			if len(attrs) == maxAttrs {
				break
			}
			attrs[clip(key, 64)] = clip(decision.Attrs[key], maxTextBytes)
		}
		decision.Attrs = attrs
	}
	return fit(decision)
}

// fit sheds optional evidence until the encoded record is within
// MaxRecordBytes, so the durable copy is never refused for its size: the
// per-field bounds alone allow more than that once JSON escaping is
// counted. Attributes go first, then alternatives, related IDs and signals
// (newest listed last, dropped first), then the free text is shortened.
func fit(decision Decision) Decision {
	size := func() int {
		data, err := json.Marshal(decision)
		if err != nil {
			return 0
		}
		return len(data)
	}
	for size() > MaxRecordBytes {
		switch {
		case len(decision.Attrs) > 0:
			keys := slices.Sorted(maps.Keys(decision.Attrs))
			delete(decision.Attrs, keys[len(keys)-1])
		case len(decision.Alternatives) > 0:
			decision.Alternatives = decision.Alternatives[:len(decision.Alternatives)-1]
		case len(decision.Related) > 0:
			decision.Related = decision.Related[:len(decision.Related)-1]
		case len(decision.Signals) > 0:
			decision.Signals = decision.Signals[:len(decision.Signals)-1]
		case len(decision.Outcome) > 0:
			decision.Outcome = ""
		case len(decision.Reason) > maxTextBytes/4:
			decision.Reason = clip(decision.Reason, len(decision.Reason)/2)
		case len(decision.Summary) > maxTextBytes/4:
			decision.Summary = clip(decision.Summary, len(decision.Summary)/2)
		default:
			return decision
		}
	}
	return decision
}

// Root reports whether the decision starts a chain.
func (decision Decision) Root() bool { return decision.ParentID == "" }

func clip(value string, limit int) string {
	if len(value) <= limit {
		return value
	}
	cut := limit
	for cut > 0 && !utf8Start(value[cut]) {
		cut--
	}
	return value[:cut]
}

func utf8Start(b byte) bool { return b&0xC0 != 0x80 }

func New() string { return NewAt(time.Now()) }

// NewAt stamps an ID with the record's time. The entropy reader is shared and
// serialized because the library's monotonic reader is not concurrency-safe.
func NewAt(at time.Time) string {
	mu.Lock()
	defer mu.Unlock()
	return ulid.MustNew(ulid.Timestamp(at), entropy).String()
}

// Parse accepts only nonzero, uppercase, 26-character Crockford ULIDs.
func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

journal_query.text:
func (journal *Journal) Query(ctx context.Context, query Query) (Result, error) {
	query = query.Normalized()
	// The replay flag is read before the snapshot: a replay that ends in
	// between leaves the result conservatively partial, never the reverse.
	replaying := journal.replaying.Load()
	decisions, coveredFrom := journal.snapshot()
	result := Result{}
	seen := make(map[string]struct{}, len(decisions))
	// fresh counts matches newer than coveredFrom. Memory evicts by arrival,
	// not by time, so only those are known to outrank everything evicted.
	fresh := 0
	for _, decision := range decisions {
		if query.Matches(decision) {
			result.Decisions = append(result.Decisions, decision)
			seen[decision.ID] = struct{}{}
			if decision.Time.After(coveredFrom) {
				fresh++
			}
		}
	}
	// While the stream tail is still replaying, memory does not hold the
	// region's history yet.
	if replaying {
		result.Partial = true
	}
	// Older decisions only matter when memory did not fill the page with
	// decisions newer than anything it evicted.
	older := !coveredFrom.IsZero() && (query.Since.IsZero() || query.Since.Before(coveredFrom))
	exhausted := !older
	if older && fresh < query.Limit {
		_, archive := journal.currentStorage()
		if archive == nil {
			result.Partial = true
		} else if complete, reachedFloor := journal.scanArchive(ctx, archive, query, coveredFrom, seen, &result); !complete {
			result.Partial = true
		} else {
			exhausted = reachedFloor
		}
	}
	SortNewestFirst(result.Decisions)
	switch {
	case len(result.Decisions) > query.Limit:
		result.Decisions = result.Decisions[:query.Limit]
		result.Truncated = true
	case len(result.Decisions) == query.Limit && !exhausted:
		// A full page with older history left unsearched may not be all:
		// say so rather than look exhaustive.
		result.Truncated = true
	}
	return result, nil
}

// archiveClockSkew is how far past the in-memory coverage a record's own
// time may lie while older archived records still follow it: the stream is
// ordered by publication, records are timed by the recording controller's
// clock and published asynchronously.
const archiveClockSkew = 5 * time.Minute

// scanArchive adds matching archived decisions recorded at or before
// coveredFrom to result. The archive is read oldest first from a start time,
// so it is searched in windows reaching back from coveredFrom that widen
// fourfold until the page is full or the query's start (or the retention)
// is reached. A page is then the newest matches, not the oldest ones a
// single scan from the start would return when the range holds more than
// maxArchiveScan records. It reports whether the search was complete and
// whether it reached the query's start (so nothing older remains).
func (journal *Journal) scanArchive(ctx context.Context, archive Archive, query Query, coveredFrom time.Time,
	seen map[string]struct{}, result *Result,
) (complete, reachedFloor bool) {
	// The search reaches back from the earlier of coveredFrom and the
	// query's end, so a historical query does not spend its scan budget on
	// newer records that cannot match.
	upper := coveredFrom
	if !query.Until.IsZero() && query.Until.Before(upper) {
		upper = query.Until
	}
	floor := query.Since
	if floor.IsZero() {
		floor = upper.Add(-DefaultRetention)
	}
	if floor.After(upper) {
		return true, true
	}
	budget := maxArchiveScan
	for width := archiveFirstWindow; ; width *= 4 {
		since := upper.Add(-width)
		if !since.After(floor) {
			since = floor
		}
		scanned := 0
		complete, err := archive.Scan(ctx, since, budget, func(decision Decision) bool {
			// Memory is complete only after coveredFrom, and nothing after
			// upper matches. The archive is in publication order, so a
			// record timed after upper is skipped, not a stopping point,
			// until well past any clock skew.
			if decision.Time.After(upper) {
				return !decision.Time.After(upper.Add(archiveClockSkew))
			}
			scanned++
			if _, dup := seen[decision.ID]; !dup && query.Matches(decision) {
				seen[decision.ID] = struct{}{}
				result.Decisions = append(result.Decisions, decision)
			}
			return true
		})
		if err != nil || !complete {
			return false, false
		}
		if since.Equal(floor) {
			return true, true
		}
		if len(result.Decisions) >= query.Limit {
			return true, false
		}
		if budget -= max(scanned, 1); budget <= 0 {
			return false, false
		}
	}
}

func (query Query) Normalized() Query {
	if query.Limit <= 0 {
		query.Limit = DefaultQueryLimit
	}
	query.Limit = min(query.Limit, MaxQueryLimit)
	query.Regions = slices.Clone(query.Regions)
	for index, region := range query.Regions {
		query.Regions[index] = strings.ToLower(region)
	}
	query.Subject = strings.ToLower(query.Subject)
	return query
}

// Matches reports whether a decision satisfies every filter of a normalized
// query.
func (query Query) Matches(decision Decision) bool {
	if len(query.Regions) > 0 && !slices.Contains(query.Regions, decision.Region) {
		return false
	}
	if len(query.Kinds) > 0 && !slices.Contains(query.Kinds, decision.Kind) {
		return false
	}
	if len(query.Actors) > 0 && !slices.ContainsFunc(query.Actors, func(actor string) bool {
		return actor == decision.Actor.Slice || actor == decision.Actor.Slice+"/"+decision.Actor.Member
	}) {
		return false
	}
	if query.SubjectKind != "" && query.SubjectKind != decision.Subject.Kind {
		return false
	}
	if query.SubjectID != "" && query.SubjectID != decision.Subject.ID {
		return false
	}
	if query.Subject != "" && !containsFold(decision.Subject.ID, query.Subject) &&
		!containsFold(decision.Subject.Name, query.Subject) && !containsFold(decision.Summary, query.Subject) {
		return false
	}
	if len(query.Statuses) > 0 && !slices.Contains(query.Statuses, decision.Status) {
		return false
	}
	if query.ParentID != "" && query.ParentID != decision.ParentID {
		return false
	}
	if !query.Since.IsZero() && decision.Time.Before(query.Since) {
		return false
	}
	if !query.Until.IsZero() && !decision.Time.Before(query.Until) {
		return false
	}
	return true
}

func containsFold(value, lowerNeedle string) bool {
	return value != "" && strings.Contains(strings.ToLower(value), lowerNeedle)
}

// SortNewestFirst orders decisions by time, newest first, breaking ties by
// ID so merged regional results are stable.
func SortNewestFirst(decisions []Decision) {
	slices.SortStableFunc(decisions, func(left, right Decision) int {
		if order := right.Time.Compare(left.Time); order != 0 {
			return order
		}
		return cmp.Compare(right.ID, left.ID)
	})
}

journal_chain.text:
func (journal *Journal) Chain(ctx context.Context, id string) (Chain, error) {
	// While the tail replays, later steps of an indexed chain (a completion
	// or a rollback) may still be pending, so every answer is partial.
	replaying := journal.replaying.Load()
	decisions, coveredFrom := journal.snapshot()
	chain, ok := BuildChain(decisions, id)
	needArchive := !ok || (!coveredFrom.IsZero() && !chain.Root.Time.After(coveredFrom)) ||
		(ok && chain.Root.ParentID != "")
	if !needArchive {
		chain.Partial = replaying
		return chain, nil
	}
	_, archive := journal.currentStorage()
	if archive == nil {
		if ok {
			// Part of the chain lies before memory and nothing can read it.
			chain.Partial = true
			return chain, nil
		}
		if replaying {
			return Chain{}, ErrUnavailable
		}
		return Chain{}, ErrNotFound
	}
	since, valid := IDTime(id)
	if ok {
		since = chain.Root.Time
		valid = true
	}
	retentionFloor := journal.config.Now().Add(-DefaultRetention)
	if !valid {
		// A caller-chosen ID (for example a managed update admission)
		// encodes no time: search the archive's whole retention.
		since = retentionFloor.Add(24 * time.Hour)
	}
	seen := make(map[string]struct{}, len(decisions))
	for _, decision := range decisions {
		seen[decision.ID] = struct{}{}
	}
	// A parent is recorded before its child; look back a little for roots
	// that the in-memory window no longer holds, then further back to the
	// time a missing parent's ID encodes, within retention.
	since = since.Add(-24 * time.Hour)
	partial := false
	for range 4 {
		complete, err := archive.Scan(ctx, since, maxArchiveScan, func(decision Decision) bool {
			if _, dup := seen[decision.ID]; !dup {
				seen[decision.ID] = struct{}{}
				decisions = append(decisions, decision)
			}
			return true
		})
		if err != nil || !complete {
			partial = true
			break
		}
		chain, ok = BuildChain(decisions, id)
		if !ok || chain.Root.ParentID == "" {
			break
		}
		parentTime, known := IDTime(chain.Root.ParentID)
		if !known {
			// The missing parent has a caller-chosen ID: widen to the
			// retention once.
			if !since.After(retentionFloor) {
				break
			}
			since = retentionFloor
			continue
		}
		if !parentTime.Before(since) || parentTime.Before(retentionFloor) {
			break
		}
		since = parentTime.Add(-time.Minute)
	}
	chain, ok = BuildChain(decisions, id)
	switch {
	case !ok && (partial || replaying):
		// The archive could not be read: not proof of absence.
		return Chain{}, ErrUnavailable
	case !ok:
		return Chain{}, ErrNotFound
	}
	chain.Partial = partial || replaying
	return chain, nil
}

func IDTime(id string) (time.Time, bool) {
	parsed, err := entityid.Parse(id)
	if err != nil || parsed.Time() == 0 {
		return time.Time{}, false
	}
	return time.UnixMilli(int64(parsed.Time())).UTC(), true
}

func BuildChain(decisions []Decision, id string) (Chain, bool) {
	byID := make(map[string]Decision, len(decisions))
	children := map[string][]string{}
	for _, decision := range decisions {
		byID[decision.ID] = decision
		if decision.ParentID != "" {
			children[decision.ParentID] = append(children[decision.ParentID], decision.ID)
		}
	}
	current, ok := byID[id]
	if !ok {
		return Chain{}, false
	}
	seen := map[string]bool{current.ID: true}
	for current.ParentID != "" {
		parent, found := byID[current.ParentID]
		if !found || seen[parent.ID] {
			break
		}
		seen[parent.ID] = true
		current = parent
	}
	chain := Chain{Root: current}
	visited := map[string]bool{}
	queue := []string{current.ID}
	// The walk is bounded by the input; only the returned list is capped,
	// after Latest is known.
	for len(queue) > 0 {
		next := queue[0]
		queue = queue[1:]
		if visited[next] {
			continue
		}
		visited[next] = true
		chain.Decisions = append(chain.Decisions, byID[next])
		queue = append(queue, children[next]...)
	}
	slices.SortStableFunc(chain.Decisions, func(left, right Decision) int {
		if order := left.Time.Compare(right.Time); order != 0 {
			return order
		}
		return cmp.Compare(left.ID, right.ID)
	})
	chain.Latest = chain.Decisions[len(chain.Decisions)-1]
	if len(chain.Decisions) > MaxQueryLimit {
		chain.Truncated = true
		kept := make([]Decision, 0, MaxQueryLimit)
		newest := chain.Decisions[len(chain.Decisions)-(MaxQueryLimit-2):]
		for _, decision := range chain.Decisions[:len(chain.Decisions)-len(newest)] {
			if decision.ID == chain.Root.ID || decision.ID == id {
				kept = append(kept, decision)
			}
		}
		chain.Decisions = append(kept, newest...)
	}
	return chain, true
}

func New() string { return NewAt(time.Now()) }

// NewAt stamps an ID with the record's time. The entropy reader is shared and
// serialized because the library's monotonic reader is not concurrency-safe.
func NewAt(at time.Time) string {
	mu.Lock()
	defer mu.Unlock()
	return ulid.MustNew(ulid.Timestamp(at), entropy).String()
}

// Parse accepts only nonzero, uppercase, 26-character Crockford ULIDs.
func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

