func OpenStream(ctx context.Context, js jetstream.JetStream, config StreamConfig) (*Stream, error) {
	if js == nil {
		return nil, errors.New("decision stream requires JetStream")
	}
	if config.Replicas < 1 || config.Replicas > 5 {
		return nil, errors.New("decision stream replica count is out of range")
	}
	subject, err := protocol.ObservabilitySubject(config.Cell, JournalLeaf)
	if err != nil {
		return nil, err
	}
	if config.Retention <= 0 {
		config.Retention = DefaultRetention
	}
	if config.MaxBytes <= 0 {
		config.MaxBytes = DefaultStreamBytes
	}
	stream, err := js.CreateOrUpdateStream(ctx, jetstream.StreamConfig{
		Name:        StreamName,
		Description: "Regional orchestrator decision journal",
		Subjects:    []string{subject},
		Storage:     jetstream.FileStorage,
		Replicas:    config.Replicas,
		Retention:   jetstream.LimitsPolicy,
		Discard:     jetstream.DiscardOld,
		MaxAge:      config.Retention,
		MaxBytes:    config.MaxBytes,
		MaxMsgs:     defaultStreamMsgs,
		MaxMsgSize:  MaxRecordBytes + 1024,
		Duplicates:  2 * time.Minute,
	})
	if err != nil {
		return nil, fmt.Errorf("open decision stream: %w", err)
	}
	return &Stream{stream: stream, js: js, subject: subject}, nil
}

// Publish stores one decision, deduplicated by its ID.
func (stream *Stream) Publish(ctx context.Context, decision Decision) error {
	data, err := json.Marshal(decision)
	if err != nil {
		return err
	}
	if len(data) > MaxRecordBytes {
		return errors.New("decision record exceeds its size bound")
	}
	_, err = stream.js.Publish(ctx, stream.subject, data, jetstream.WithMsgID(decision.ID))
	return err
}

// Scan visits stored decisions from since, oldest first.
func (stream *Stream) Scan(ctx context.Context, since time.Time, maxScan int, visit func(Decision) bool) (bool, error) {
	info, err := stream.stream.Info(ctx)
	if err != nil {
		return false, err
	}
	if info.State.Msgs == 0 || info.State.LastTime.Before(since) {
		return true, nil
	}
	config := jetstream.OrderedConsumerConfig{DeliverPolicy: jetstream.DeliverAllPolicy}
	if !since.IsZero() && since.After(info.State.FirstTime) {
		start := since.UTC()
		config = jetstream.OrderedConsumerConfig{DeliverPolicy: jetstream.DeliverByStartTimePolicy,
			OptStartTime: &start}
	}
	return stream.consume(ctx, config, maxScan, info.State.LastSeq, visit)
}

// consume reads an ordered consumer until it reaches lastSeq, maxScan
// records, or visit stops it.
func (stream *Stream) consume(ctx context.Context, config jetstream.OrderedConsumerConfig, maxScan int,
	lastSeq uint64, visit func(Decision) bool,
) (bool, error) {
	consumer, err := stream.stream.OrderedConsumer(ctx, config)
	if err != nil {
		return false, err
	}
	scanned := 0
	for scanned < maxScan {
		batch, err := consumer.Fetch(min(fetchBatch, maxScan-scanned), jetstream.FetchMaxWait(time.Second))
		if err != nil {
			return false, err
		}
		received := 0
		for message := range batch.Messages() {
			received++
			scanned++
			metadata, err := message.Metadata()
			if err != nil {
				continue
			}
			var decision Decision
			if json.Unmarshal(message.Data(), &decision) == nil && decision.ID != "" && !visit(decision) {
				return true, nil
			}
			if metadata.Sequence.Stream >= lastSeq || metadata.NumPending == 0 {
				return true, nil
			}
		}
		if err := batch.Error(); err != nil && !errors.Is(err, jetstream.ErrNoMessages) {
			return false, err
		}
		if received == 0 {
			// Nothing more arrived within the wait: the stream end.
			return true, nil
		}
		if ctx.Err() != nil {
			return false, ctx.Err()
		}
	}
	return false, nil
}

func (stream *Stream) Tail(ctx context.Context, journal *Journal, warm int) error {
	if warm <= 0 {
		warm = journal.config.Capacity
	}
	journal.beginReplay()
	defer journal.endReplay()
	backoff := time.Second
	// next is the sequence to resume from. caughtUp is the last sequence
	// the stream held when the tail started; it survives consumer restarts
	// so a replay broken half way still ends once that sequence is read.
	var next, caughtUp uint64
	for ctx.Err() == nil {
		err := stream.tailOnce(ctx, journal, warm, &next, &caughtUp)
		if ctx.Err() != nil {
			return ctx.Err()
		}
		slog.DebugContext(ctx, "decision stream tail restarting", observability.ComponentKey, "decision", "error", err)
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-time.After(backoff):
		}
		backoff = min(backoff*2, 30*time.Second)
	}
	return ctx.Err()
}

func (stream *Stream) tailOnce(ctx context.Context, journal *Journal, warm int, next, caughtUp *uint64) error {
	// An empty stream is read from its start, so a decision stored between
	// the info call and the consumer is not missed.
	config := jetstream.OrderedConsumerConfig{DeliverPolicy: jetstream.DeliverAllPolicy}
	if *next == 0 {
		info, err := stream.stream.Info(ctx)
		if err != nil {
			return err
		}
		if info.State.Msgs == 0 {
			journal.endReplay()
		}
		*caughtUp = info.State.LastSeq
		if info.State.Msgs > 0 {
			start := info.State.FirstSeq
			if info.State.LastSeq >= uint64(warm) && info.State.LastSeq-uint64(warm)+1 > start {
				start = info.State.LastSeq - uint64(warm) + 1
			}
			if start > info.State.FirstSeq {
				// Older decisions stay in the stream for archive queries.
				if message, err := stream.stream.GetMsg(ctx, start); err == nil {
					journal.MarkCoveredFrom(message.Time)
				}
			}
			config = jetstream.OrderedConsumerConfig{DeliverPolicy: jetstream.DeliverByStartSequencePolicy,
				OptStartSeq: start}
		}
	} else {
		config = jetstream.OrderedConsumerConfig{DeliverPolicy: jetstream.DeliverByStartSequencePolicy,
			OptStartSeq: *next}
	}
	consumer, err := stream.stream.OrderedConsumer(ctx, config)
	if err != nil {
		return err
	}
	messages, err := consumer.Messages()
	if err != nil {
		return err
	}
	defer messages.Stop()
	stop := context.AfterFunc(ctx, messages.Stop)
	defer stop()
	for {
		message, err := messages.Next()
		if err != nil {
			return err
		}
		var sequence uint64
		if metadata, err := message.Metadata(); err == nil {
			sequence = metadata.Sequence.Stream
			*next = sequence + 1
		}
		var decision Decision
		if json.Unmarshal(message.Data(), &decision) == nil && decision.ID != "" {
			journal.Ingest(decision)
		}
		if *caughtUp > 0 && sequence >= *caughtUp {
			// Memory now holds what the stream held when the tail started.
			journal.endReplay()
			*caughtUp = 0
		}
	}
}

federation.text:
func (federation Federation) Query(ctx context.Context, query Query) (Result, error) {
	query = query.Normalized()
	regions := federation.regions(query.Regions)
	results := make([]Result, len(regions))
	statuses := make([]RegionStatus, len(regions))
	var group sync.WaitGroup
	for index, region := range regions {
		group.Go(func() {
			regional := query
			if region != "" {
				regional.Regions = []string{region}
			}
			result, status := federation.queryRegion(ctx, region, regional)
			results[index], statuses[index] = result, status
		})
	}
	group.Wait()
	merged := Result{Regions: statuses}
	for _, result := range results {
		merged.Decisions = append(merged.Decisions, result.Decisions...)
		merged.Truncated = merged.Truncated || result.Truncated
		merged.Partial = merged.Partial || result.Partial
	}
	for _, status := range statuses {
		// A configured region that is not linked was not searched either.
		if status.State != RegionOK {
			merged.Partial = true
		}
	}
	SortNewestFirst(merged.Decisions)
	if len(merged.Decisions) > query.Limit {
		merged.Decisions = merged.Decisions[:query.Limit]
		merged.Truncated = true
	}
	return merged, nil
}

func (federation Federation) regions(filter []string) []string {
	var all []string
	local := ""
	if federation.Links != nil {
		all = federation.Links.Regions()
		local = federation.Links.Local()
	}
	if len(all) == 0 && federation.Local != nil {
		all = []string{local}
	}
	if len(filter) == 0 {
		return all
	}
	return slices.DeleteFunc(all, func(region string) bool { return !slices.Contains(filter, region) })
}

func (federation Federation) queryRegion(ctx context.Context, region string, query Query) (Result, RegionStatus) {
	status := RegionStatus{Region: region}
	if federation.Local != nil && (federation.Links == nil || region == federation.Links.Local()) {
		result, err := federation.Local.Query(ctx, query)
		if err != nil {
			status.State, status.Detail = RegionError, "local journal unavailable"
			return Result{}, status
		}
		status.State, status.Count = RegionOK, len(result.Decisions)
		return result, status
	}
	reply, err := federation.request(ctx, region, remoteRequest{Version: wireVersion, Query: query})
	if err != nil {
		status.State, status.Detail = classify(err)
		return Result{}, status
	}
	if reply.Result == nil {
		status.State, status.Detail = RegionError, "region returned no result"
		return Result{}, status
	}
	result := *reply.Result
	// Never trust a remote region to answer for another one.
	result.Decisions = slices.DeleteFunc(result.Decisions, func(decision Decision) bool {
		return decision.Region != region
	})
	status.State, status.Count = RegionOK, len(result.Decisions)
	return result, status
}

// Chain looks the chain up locally first, then in every linked region.
func (federation Federation) Chain(ctx context.Context, id string) (Chain, error) {
	// Keep searching past a journal that cannot answer (this member's while
	// it replays or its archive fails, or a linked region's), but do not
	// turn its failure into a negative answer: ErrNotFound only when every
	// searched journal answered that it has no such decision.
	var unavailable error
	if federation.Local != nil {
		chain, err := federation.Local.Chain(ctx, id)
		if err == nil {
			return chain, nil
		}
		if !errors.Is(err, ErrNotFound) {
			unavailable = err
		}
	}
	if federation.Links == nil {
		if unavailable != nil {
			return Chain{}, unavailable
		}
		return Chain{}, ErrNotFound
	}
	for _, region := range federation.Links.Regions() {
		if region == federation.Links.Local() {
			continue
		}
		if !federation.Links.Linked(region) {
			// A configured region without a link was never searched, so
			// a final miss is not proof of absence.
			if unavailable == nil {
				unavailable = ErrUnavailable
			}
			continue
		}
		reply, err := federation.request(ctx, region, remoteRequest{Version: wireVersion, ChainID: id})
		switch {
		case err == nil && reply.Chain != nil:
			return *reply.Chain, nil
		case err != nil && !errors.Is(err, ErrNotFound) && unavailable == nil:
			unavailable = ErrUnavailable
		}
	}
	if unavailable != nil {
		return Chain{}, unavailable
	}
	return Chain{}, ErrNotFound
}

func (federation Federation) request(ctx context.Context, region string, request remoteRequest) (remoteReply, error) {
	if federation.Links == nil {
		return remoteReply{}, regionlink.ErrNotLinked
	}
	payload, err := json.Marshal(request)
	if err != nil {
		return remoteReply{}, err
	}
	data, err := federation.Links.Request(ctx, region, QueryLeaf, payload)
	if err != nil {
		return remoteReply{}, err
	}
	var reply remoteReply
	if err := json.Unmarshal(data, &reply); err != nil || reply.Version != wireVersion {
		return remoteReply{}, errors.New("invalid decision reply")
	}
	if reply.Error != "" {
		if reply.Error == "not_found" {
			return remoteReply{}, ErrNotFound
		}
		return remoteReply{}, errors.New("region could not answer")
	}
	return reply, nil
}

func classify(err error) (state, detail string) {
	switch {
	case errors.Is(err, regionlink.ErrNotLinked):
		return RegionNotLinked, "no cross-region link yet"
	case errors.Is(err, context.DeadlineExceeded), errors.Is(err, nats.ErrTimeout), errors.Is(err, nats.ErrNoResponders):
		return RegionUnreachable, "region did not answer"
	default:
		return RegionError, "region query failed"
	}
}

func New(local string, conn *nats.Conn, configured []string, timeout time.Duration) (*Links, error) {
	token, err := protocol.RegionToken(local)
	if err != nil {
		return nil, err
	}
	if timeout <= 0 {
		timeout = DefaultTimeout
	}
	links := &Links{local: token, timeout: timeout, conns: map[string]*nats.Conn{}}
	links.regions = append(links.regions, token)
	for _, region := range configured {
		if regionToken, err := protocol.RegionToken(region); err == nil && regionToken != protocol.GlobalScope &&
			!slices.Contains(links.regions, regionToken) {
			links.regions = append(links.regions, regionToken)
		}
	}
	slices.Sort(links.regions[1:])
	if conn != nil {
		links.conns[token] = conn
	}
	return links, nil
}

// Link attaches (or with a nil conn, detaches) a region's connection. An
// unconfigured region is added to the configured set.
func (links *Links) Link(region string, conn *nats.Conn) error {
	token, err := protocol.RegionToken(region)
	if err != nil || token == protocol.GlobalScope {
		return protocol.ErrInvalidSubjectToken
	}
	links.mu.Lock()
	defer links.mu.Unlock()
	if !slices.Contains(links.regions, token) {
		links.regions = append(links.regions, token)
		slices.Sort(links.regions[1:])
	}
	if conn == nil {
		delete(links.conns, token)
	} else {
		links.conns[token] = conn
	}
	return nil
}

// Local returns this member's region token.
func (links *Links) Local() string { return links.local }

// Regions returns every configured region, local first.
func (links *Links) Regions() []string {
	links.mu.RLock()
	defer links.mu.RUnlock()
	return slices.Clone(links.regions)
}

// Linked reports whether region has a connection.
func (links *Links) Linked(region string) bool {
	links.mu.RLock()
	defer links.mu.RUnlock()
	_, ok := links.conns[strings.ToLower(region)]
	return ok
}

// Request sends one read-only request to region's observability leaf.
func (links *Links) Request(ctx context.Context, region, leaf string, payload []byte) ([]byte, error) {
	region = strings.ToLower(region)
	links.mu.RLock()
	conn, linked := links.conns[region]
	configured := slices.Contains(links.regions, region)
	links.mu.RUnlock()
	if !configured {
		return nil, ErrUnknownRegion
	}
	if !linked {
		return nil, ErrNotLinked
	}
	subject, err := protocol.ObservabilitySubject(region, leaf)
	if err != nil {
		return nil, err
	}
	// Always bound the request by the link timeout; an earlier caller
	// deadline still wins, a later one does not stretch it.
	ctx, cancel := context.WithTimeout(ctx, links.timeout)
	defer cancel()
	message, err := conn.RequestMsgWithContext(ctx, &nats.Msg{Subject: subject, Data: payload, Header: observability.TraceHeader(ctx, nil)})
	if err != nil {
		return nil, err
	}
	return message.Data, nil
}

