func ServeQueries(ctx context.Context, conn *nats.Conn, cell string, source Source) (*nats.Subscription, error) {
	if conn == nil || source == nil {
		return nil, errors.New("decision query responder requires a connection and a source")
	}
	subject, err := protocol.ObservabilitySubject(cell, QueryLeaf)
	if err != nil {
		return nil, err
	}
	region := strings.ToLower(cell)
	// A queue group sends each query to one controller instead of all.
	subscription, err := conn.QueueSubscribe(subject, "decisionlog", func(message *nats.Msg) {
		if message.Reply == "" || len(message.Data) > maxQueryRequestBytes {
			return
		}
		reply, requested := answer(observability.ContinueTrace(ctx, message.Header.Get("traceparent")), region, source, message.Data)
		data, err := encodeReply(reply, requested, conn.MaxPayload())
		if err != nil {
			return
		}
		_ = message.Respond(data)
	})
	if err != nil {
		return nil, err
	}
	context.AfterFunc(ctx, func() { _ = subscription.Unsubscribe() })
	return subscription, nil
}

// answer handles one request and also returns the requested chain ID, which
// encodeReply must keep when it trims an oversized chain.
func answer(ctx context.Context, region string, source Source, data []byte) (remoteReply, string) {
	reply, request := answerRequest(ctx, region, source, data)
	return reply, request.ChainID
}

func answerRequest(ctx context.Context, region string, source Source, data []byte) (remoteReply, remoteRequest) {
	reply := remoteReply{Version: wireVersion, Region: region}
	// Peer regions reach this subject over the interregion contract, so the
	// request is decoded strictly and bounded before anything reads it.
	var request remoteRequest
	if err := protocol.DecodeStrict(data, &request, maxQueryRequestBytes); err != nil ||
		request.Version != wireVersion || !request.valid() {
		reply.Error = "invalid"
		return reply, remoteRequest{}
	}
	answerCtx, cancel := context.WithTimeout(ctx, queryAnswerTimeout)
	defer cancel()
	if request.ChainID != "" {
		chain, err := source.Chain(answerCtx, request.ChainID)
		switch {
		case errors.Is(err, ErrNotFound):
			reply.Error = "not_found"
		case err != nil:
			reply.Error = "unavailable"
		default:
			reply.Chain = &chain
		}
		return reply, request
	}
	// A remote region answers only for itself.
	request.Query.Regions = []string{region}
	result, err := source.Query(answerCtx, request.Query)
	if err != nil {
		reply.Error = "unavailable"
		return reply, request
	}
	reply.Result = &result
	return reply, request
}

func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

// DecodeTolerant is DecodeStrict for records a newer binary may have written:
// it skips members this binary does not know, so binary N-1 reads N's records.
// Duplicate names, invalid UTF-8 and the size limit still fail. A record's
// schema version names its breaking changes, and its reader checks it; a new
// member needs a safe zero value, since an older writer drops it.
func DecodeTolerant(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, false)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}

	if region == "" || len(region) > 63 {
		return "", fmt.Errorf("%w: region length is out of bounds", ErrInvalidSubjectToken)
	}
	region = strings.ToUpper(region)
	if region == "GLOBAL" {
		return region, nil
	}
	previousHyphen := true
	for _, character := range region {
		if character == '-' {
			if previousHyphen {
				return "", ErrInvalidSubjectToken
			}
			previousHyphen = true
			continue
		}
		if character < 'A' || character > 'Z' {
			if character < '0' || character > '9' {
				return "", ErrInvalidSubjectToken
			}
		}
		previousHyphen = false
	}
	if previousHyphen {
		return "", ErrInvalidSubjectToken
	}
	return region, nil
}

func RegionToken(region string) (string, error) {
	canonical, err := CanonicalRegion(region)
	if err != nil {
		return "", err
	}
	return strings.ToLower(canonical), nil
}

func RegionalRoot(region string) (string, error) {
	token, err := RegionToken(region)
	if err != nil || token == GlobalScope {
		return "", ErrInvalidSubjectToken
	}
	return SubjectRoot + "." + token, nil
}

func QuerySubject(region, query string) (string, error) {
	return regionalSubject(region, "query", query)
}

func CommandSubject(region, command string) (string, error) {
	return regionalSubject(region, "command", command)
}

// ObservabilitySubject is a read-only member telemetry route inside one
// regional cell, for example ts.orch.v1.gru.obs.snapshot. Every controller
// answers it; it carries no signed state and never drives a mutation.
// ObservabilityGrant (families.go) is the subscribe grant covering every leaf.
func ObservabilitySubject(region, leaf string) (string, error) {
	return regionalSubject(region, "obs", leaf)
}

func ValidateSubjectToken(token string) error {
	if !validToken(token) {
		return ErrInvalidSubjectToken
	}
	return nil
}

func regionalSubject(region, family, leaf string) (string, error) {
	if err := ValidateSubjectToken(leaf); err != nil {
		return "", err
	}
	root, err := RegionalRoot(region)
	if err != nil {
		return "", err
	}
	return root + "." + family + "." + leaf, nil
}

func agentSubject(region, nodeID, family, leaf string) (string, error) {
	if !validIdentity(nodeID, 512) {
		return "", fmt.Errorf("%w: invalid node identity", ErrInvalidSubjectToken)
	}
	root, err := RegionalRoot(region)
	if err != nil {
		return "", err
	}
	if err := ValidateSubjectToken(leaf); err != nil {
		return "", err
	}
	return root + ".agent." + HashToken(nodeID) + "." + family + "." + leaf, nil
}

func validToken(token string) bool {
	if token == "" || len(token) > 63 || token[0] == '-' || token[len(token)-1] == '-' {
		return false
	}
	for _, character := range token {
		if character == '-' || character == '_' {
			continue
		}
		if character < 'a' || character > 'z' {
			if character < '0' || character > '9' {
				return false
			}
		}
	}
	return true
}

func StartTrace(ctx context.Context) context.Context {
	id := ulid.MustParse(entityid.New())
	return context.WithValue(ctx, traceKey{}, hex.EncodeToString(id[:]))
}

// ContinueTrace reuses the trace of a valid traceparent and starts a new trace
// otherwise.
func ContinueTrace(ctx context.Context, traceparent string) context.Context {
	match := traceparentPattern.FindStringSubmatch(traceparent)
	if match == nil || strings.Trim(match[1], "0") == "" || strings.Trim(match[2], "0") == "" {
		return StartTrace(ctx)
	}
	return context.WithValue(ctx, traceKey{}, match[1])
}

// TraceID returns the 32-character trace ID of ctx, or "" when it has none.
func TraceID(ctx context.Context) string {
	trace, _ := ctx.Value(traceKey{}).(string)
	return trace
}

// Traceparent renders the trace of ctx as a traceparent with a new random span
// ID, or "" when ctx has no trace.
func Traceparent(ctx context.Context) string {
	trace := TraceID(ctx)
	if trace == "" {
		return ""
	}
	var span [8]byte
	for span == [8]byte{} {
		_, _ = rand.Read(span[:])
	}
	return "00-" + trace + "-" + hex.EncodeToString(span[:]) + "-01"
}

// TraceHeader sets the traceparent of ctx on header, allocating it when nil.
// A context without a trace returns header unchanged.
func TraceHeader(ctx context.Context, header nats.Header) nats.Header {
	traceparent := Traceparent(ctx)
	if traceparent == "" {
		return header
	}
	if header == nil {
		header = nats.Header{}
	}
	header.Set(traceparentHeader, traceparent)
	return header
}

