func Run(ctx context.Context, args []string, out io.Writer) error {
	if len(args) == 0 || args[0] == "--help" || args[0] == "-h" || args[0] == "help" {
		_, err := io.WriteString(out, usage)
		return err
	}
	if args[0] != "replicate" {
		return fmt.Errorf("unknown disaster-recovery command %q", args[0])
	}
	fs := flag.NewFlagSet("disaster-recovery replicate", flag.ContinueOnError)
	fs.SetOutput(out)
	fs.Usage = func() { _, _ = io.WriteString(out, usage) }
	path := fs.String("config", "", "pinned cross-region recovery configuration")
	apply := fs.Bool("apply", false, "create the missing recovery resources")
	if err := fs.Parse(args[1:]); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return nil
		}
		return err
	}
	if fs.NArg() != 0 || *path == "" {
		return errors.New("replicate requires --config and takes only flags")
	}
	file, err := os.Open(*path)
	if err != nil {
		return err
	}
	data, err := io.ReadAll(io.LimitReader(file, (64<<10)+1))
	err = errors.Join(err, file.Close())
	if err != nil {
		return err
	}
	var config Config
	if err := protocol.DecodeStrict(data, &config, 64<<10); err != nil {
		return err
	}
	if err := config.Validate(); err != nil {
		return err
	}
	for _, name := range ociclient.SecretUnsafeEnv {
		if _, set := os.LookupEnv(name); set {
			return fmt.Errorf("unset %s before preparing recovery keys", name)
		}
	}
	gru, err := ociclient.OperatorConfig(catalog.OCIRegion(catalog.GRU))
	if err != nil {
		return err
	}
	sfo, err := ociclient.OperatorConfig(catalog.OCIRegion(catalog.SFO))
	if err != nil {
		return err
	}

var namespacePattern = regexp.MustCompile(`^[a-z0-9]{1,64}$`)
var ocidPattern = regexp.MustCompile(`^ocid1\.[a-z]+\.oc1\.[a-z0-9-]*\.[a-z0-9]+(?:\.[a-z0-9]+)*$`)
var policyIDPattern = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]*$`)

func (config Config) Validate() error {
	if config.Version != 1 || !namespacePattern.MatchString(config.Namespace) {
		return errors.New("disaster recovery config requires version 1 and an Object Storage namespace")
	}
	seenIDs := make(map[string]string)
	for cell, region := range map[string]Region{catalog.GRU: config.GRU, catalog.SFO: config.SFO} {
		if !validOCID(region.CompartmentID, "compartment", "") ||
			!validOCID(region.VaultID, "vault", catalog.OCIRegion(cell)) ||
			!validOCID(region.KeyID, "key", catalog.OCIRegion(cell)) {
			return fmt.Errorf("%s requires a control compartment and its regional Vault and key OCIDs", cell)
		}
		other := "sfo"
		if cell == catalog.SFO {
			other = "gru"
		}
		prefix := strings.ToLower(cell) + "-1-dr-" + other + "-1-"
		for name, id := range region.BucketIDs {
			if (name != prefix+"backup" && name != prefix+"backup-seed" && name != prefix+"head" && name != prefix+"head-seed") ||
				!validOCID(id, "bucket", catalog.OCIRegion(cell)) {
				return fmt.Errorf("%s has an unexpected destination bucket name or OCID: %s", cell, name)
			}
			if previous, ok := seenIDs[id]; ok {
				return fmt.Errorf("bucket %s shares its OCID with %s", name, previous)
			}
			seenIDs[id] = name
		}
		prefix = "TS-641-" + strings.ToLower(cell) + "-1-"
		for name, id := range region.PolicyIDs {
			// The SDK treats replication policy IDs as opaque strings, not OCIDs.
			if (name != prefix+"backup" && name != prefix+"head") || !policyIDPattern.MatchString(id) {
				return fmt.Errorf("%s has an unexpected replication policy name or ID: %s", cell, name)
			}
			if previous, ok := seenIDs[id]; ok {
				return fmt.Errorf("policy %s shares its ID with %s", name, previous)
			}
			seenIDs[id] = name
		}
	}
	if config.GRU.CompartmentID == config.SFO.CompartmentID {
		return errors.New("GRU and SFO control compartments must differ")
	}
	return nil
}

func validOCID(id, kind, region string) bool {
	if !ocidPattern.MatchString(id) {
		return false
	}
	parts := strings.Split(id, ".")
	return parts[1] == kind && parts[3] == region
}

// SecretUnsafeEnv are the OCI SDK variables that print request and response
// bodies or redirect endpoints and TLS trust. Callers that move secrets
// through the SDK refuse to run while any is set.
var SecretUnsafeEnv = []string{"OCI_GO_SDK_DEBUG", "OCI_METADATA_BASE_URL", "OCI_SDK_AUTH_CLIENT_REGION_URL",
	"OCI_DEFAULT_CERTS_PATH", "OCI_DEFAULT_CLIENT_CERTS_PATH", "OCI_DEFAULT_CLIENT_CERTS_PRIVATE_KEY_PATH"}

func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

// DecodeTolerant is DecodeStrict for records a newer binary may have written:
// it skips members this binary does not know, so binary N-1 reads N's records.
// Duplicate names, invalid UTF-8 and the size limit still fail. A record's
// schema version names its breaking changes, and its reader checks it; a new
// member needs a safe zero value, since an older writer drops it.
func DecodeTolerant(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, false)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
